"""V-53: a reader for the QR code the start page draws, written from ISO 18004 and independent of the page's encoder.

It takes the page's SVG, rebuilds the module grid, checks both copies of the format information (BCH) and the
function patterns, removes the mask, reads the codewords in zigzag order, un-interleaves the blocks and returns the
byte-mode text. It does not run Reed-Solomon correction (a clean render has no errors to correct); the OpenCV reader
in the V-53 evidence (`qr-decode.log`) is the second, wholly independent check. Error correction level M, versions 1-9.
"""

from __future__ import annotations

import re

ECC_PER_BLOCK_M = {1: 10, 2: 16, 3: 26, 4: 18, 5: 24, 6: 16, 7: 18, 8: 22, 9: 22}
BLOCKS_M = {1: 1, 2: 1, 3: 1, 4: 2, 5: 2, 6: 4, 7: 4, 8: 4, 9: 5}
ALIGN = {1: [], 2: [6, 18], 3: [6, 22], 4: [6, 26], 5: [6, 30], 6: [6, 34], 7: [6, 22, 38], 8: [6, 24, 42], 9: [6, 26, 46]}


def grid_from_svg(svg: str) -> list[list[bool]]:
    box = re.search(r'viewBox="0 0 (\d+) (\d+)"', svg)
    assert box and box.group(1) == box.group(2), "a square code"
    size = int(box.group(1)) - 8  # four quiet modules each side
    path = re.search(r'<path d="([^"]*)"', svg).group(1)
    grid = [[False] * size for _ in range(size)]
    for x, y, width in re.findall(r"M(\d+) (\d+)h(\d+)v1h-\d+z", path):
        for dx in range(int(width)):
            grid[int(y) - 4][int(x) - 4 + dx] = True
    return grid


def _format_valid(bits: int) -> int:
    """Return the 5 data bits when `bits` is a valid BCH(15,5) word, else -1."""
    word = bits ^ 0x5412
    data = word >> 10
    rest = data
    for _ in range(10):
        rest = (rest << 1) ^ ((rest >> 9) * 0x537)
    return data if ((data << 10) | rest) == word else -1


def _is_function(x: int, y: int, size: int, version: int) -> bool:
    if (x < 9 and y < 9) or (x >= size - 8 and y < 9) or (x < 9 and y >= size - 8):
        return True
    if x == 6 or y == 6:
        return True
    if version >= 7 and ((x >= size - 11 and y < 6) or (y >= size - 11 and x < 6)):
        return True
    positions = ALIGN[version]
    for i, cx in enumerate(positions):
        for j, cy in enumerate(positions):
            if (i == 0 and j == 0) or (i == 0 and j == len(positions) - 1) or (i == len(positions) - 1 and j == 0):
                continue
            if abs(x - cx) <= 2 and abs(y - cy) <= 2:
                return True
    return False


def _masked(mask: int, x: int, y: int) -> bool:
    return [
        (x + y) % 2 == 0, y % 2 == 0, x % 3 == 0, (x + y) % 3 == 0, (x // 3 + y // 2) % 2 == 0,
        (x * y) % 2 + (x * y) % 3 == 0, ((x * y) % 2 + (x * y) % 3) % 2 == 0, ((x + y) % 2 + (x * y) % 3) % 2 == 0,
    ][mask]


def decode(svg: str) -> str:
    grid = grid_from_svg(svg)
    size = len(grid)
    assert (size - 17) % 4 == 0, f"{size} modules is not a QR size"
